import pathlib,json,hashlib,pandas as pd,numpy as np
ROOT=pathlib.Path('/home/boltzmann13/IMRAN/NOV26/cirspr-sci-env/05_validated_benchmarks/CURRENT.txt').read_text();ROOT=pathlib.Path(ROOT)
tr=pd.read_csv(ROOT/'data/BEHive_HEK293T_BE4_efficiency.csv');te=pd.read_csv(ROOT/'data/BEHive_HEK293T_BE4_disease_external.csv')
def fields(x):
 out=[]
 for _,r in x.iterrows():
  seq=str(r['Sequence context (56nt)']).upper();zero=int(r['Protospacer position zero index']);g=str(r['gRNA (20nt)']).upper();feature=seq[zero-9:zero+22];pam=seq[zero+21:zero+24]
  valid=(len(feature)==31 and len(g)==20 and set(feature)<=set('ACGT') and feature[10:30]==g and len(pam)==3 and pam[1:]=='GG')
  out.append(dict(name=str(r['Name (unique)']),guide=g,feature31=feature,context=seq,zero_index=zero,pam=pam,valid=valid,Y=float(r['Y']) if pd.notna(r['Y']) else None,Y_weight=float(r['Y_weight']) if pd.notna(r['Y_weight']) else None))
 return pd.DataFrame(out)
a=fields(tr);b=fields(te);train_guides=set(a.guide);train_features=set(a.feature31);b['train_guide_overlap']=b.guide.isin(train_guides);b['train_feature_overlap']=b.feature31.isin(train_features);b['eligible']=b.valid&b.Y.notna()&~b.train_guide_overlap&~b.train_feature_overlap
b.to_csv(ROOT/'data/BEHive_external_intake_audit.csv',index=False);held=b[b.eligible].copy();assert len(held)>100 and not held.train_guide_overlap.any() and not held.train_feature_overlap.any();held.to_csv(ROOT/'data/BEHive_external_heldout.csv',index=False)
a[a.valid].head(20).to_csv(ROOT/'data/BEHive_feature_concordance_examples.csv',index=False)
protocol={'model':'BE-Hive efficiency released HEK293T_12kChar_BE4_bestmodel.pkl','source_model_commit':'fbd495910d6c95b24081649015d6257a8badc9d7','cell':'HEK293T','editor':'BE4, not silently renamed BE4max','training_pool':'all10409 released HEK293T12kChar BE4 processed targets, conservatively excluded by any exact20mer guide or exact31nt model feature context','external_labels':'separate HEK293T_CtoT_BE4 disease-focused library, processed experimentally measured any-base-editing efficiency','before_intake':len(b),'eligible':len(held),'known_train_guide_overlaps':int(b.train_guide_overlap.sum()),'known_train_feature_overlaps':int(b.train_feature_overlap.sum()),'invalid_sequence_contexts':int((~b.valid).sum()),'input_features':'actual31nt feature region positions-9..21, source onehot/dinucleotide/count/Tm features;50nt API has unused flanks missing in some external sequences, no fake padding used; feature equivalence tested on genuine50nt contexts','primary_endpoint':'Y: author-normalized replicate-mean logit any-edit fraction, not intended-correction rate or genotype purity','probability_calibration':'NOT_FIT; no test-label fitting of conversion mean/std; model outputs native logit score only','metrics':'Pearson/Spearman with measuredY and bootstrap intervals; source paper internal split not claimed reproduced','limitations':['Complete original hyperparameter-selection split membership not supplied; external-library benchmark uses conservative released training-pool exclusions','Not demonstrated fully gene-disjoint; no complete genome-level near-similarity exclusion','Any-edit efficiency benchmark does not validate BE-Hive bystander-genotype predictions or intended-edit purity'],'frozen_before_inference':True}
(ROOT/'protocols/BEHive_external_BE4.json').write_text(json.dumps(protocol,indent=2));print(json.dumps(protocol,indent=2))
